export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return 0;

  const otherTypes = new Set(
    army.filter((card) => !isSphinx(card)).map((card) => card.monster),
  ).size;

  if (otherTypes > 3) return 1 + 2 * (otherTypes - 3);
  return 2;
};

